__NUXT_JSONP__("/ru", (function(a,b,c,d,e){return {data:[{$axios:{request:{},getUri:{},delete:{},get:{},head:{},options:{},post:{},put:{},patch:{},defaults:{headers:{common:{Accept:"application\u002Fjson, text\u002Fplain, *\u002F*","accept-encoding":"gzip, deflate"},delete:{},get:{},head:{},post:{"Content-Type":"application\u002Fx-www-form-urlencoded"},put:{"Content-Type":"application\u002Fx-www-form-urlencoded"},patch:{"Content-Type":"application\u002Fx-www-form-urlencoded"}},baseURL:"http:\u002F\u002Flocalhost:8000",transformRequest:[{}],transformResponse:[{}],timeout:0,adapter:{},xsrfCookieName:"XSRF-TOKEN",xsrfHeaderName:"X-XSRF-TOKEN",maxContentLength:-1,maxBodyLength:-1,validateStatus:{},transitional:{silentJSONParsing:true,forcedJSONParsing:true,clarifyTimeoutError:false}},interceptors:{request:{handlers:[{fulfilled:{},rejected:void 0,synchronous:false,runWhen:null}]},response:{handlers:[]}},CancelToken:{source:{}},isCancel:{},setBaseURL:{},setHeader:{},setToken:{},onRequest:{},onResponse:{},onRequestError:{},onResponseError:{},onError:{},create:{},$request:{},$delete:{},$get:{},$head:{},$options:{},$post:{},$put:{},$patch:{}},details:{slug:b,pageTitle:c,pageDescription:c,peopleChooseMli:{title:"3 Причины почему люди выбирают MLI",subtitle:"(Mentor Language Institute)",lists:[{image:"\u002Fimages\u002Fhome\u002Fru\u002Fpeople-choose-mli-1.jpg",title:"Голливуд и Вествуд",description:"Мы находимся в прекрасных, популярных районах Лос-Анджелеса. Студенты могут не только изучать английский язык, но и наслаждаться Лос-Анджелесом.",read_more:[a]},{image:"\u002Fimages\u002Fhome\u002Fru\u002Fpeople-choose-mli-2.jpg",title:"Утром, Днем и Вечером",description:"Мы предоставляем классы «Утром», «Денем» или «Вечером» для людей, которым необходим гибкий график.",read_more:[a]},{image:"\u002Fimages\u002Fhome\u002Fru\u002Fpeople-choose-mli-3.jpg",title:"$201 \u002F 1 неделя ～",description:"Хорошее расположение и разумная цена! Пожалуйста, сравните наши цены с другими школами. Если вы хотите получить информацию об обучении, нажмите «Свяжитесь с нами» ниже",read_more:[a]}]},highlyRated:"\u002Fimages\u002Fhome\u002Fru\u002Fmli-highly-rated.jpg",courses:{title:"Курсы",lists:[{image:d,title:"ESL Программа",subtitle:["Эта программа состоит из аудирования \u002F разговора, чтения \u002F словарного запаса и классов грамматики \u002F письма. Программа ESL идеально подходит для студентов, которые хотят улучшить свои навыки английского языка в общем."]},{image:e,title:"TOEFL® Программа",subtitle:["Программа TOEFL® в MLI представляет собой интенсивный анализ навыков и стратегий, необходимых для достижения успешного результата в четырех разделах интернет-теста (iBT)."]},{image:d,title:"Программа ESL на каникулах",subtitle:["Эта программа состоит из уроков аудирования\u002Fговорения, чтения\u002Fлексики и грамматики\u002Fписьма. \u003Cbr\u003EМы предлагаем программу Vacation ESL для студентов, которые хотят изучать английский язык в течение короткого срока."]},{image:e,title:"IELTS™",subtitle:["IELTS ™ - это тест, разработанный в Великобритании и Австралии, для оценки уровня владения английским языком. В последнее время многие американские университеты требуют либо балл TOEFL®, либо балл IELTS ™.","Программа состоит из четырех частей: аудирования, речи, чтения и письма.В этом классе вы получите необходимые навыки \u002F стратегии для достижения высоких результатов в каждом разделе.","IELTS ™ считается относительно проща, чем TOEFL®. Это идеальная программа для студентов, которые находят TOEFL® трудными"]},{image:"\u002Fimages\u002Ficons\u002Fmessage.png",title:"Программа Разговорного Английского",subtitle:["Наша программа направлена на улучшение ваших разговорных навыков на английском языке с помощью увлекательных занятий и интерактивного обучения! На наших занятиях студенты изучат широкий словарный запас, фразы и идиомы, которые оживят ваш разговор. Практикуйте свое произношение в нашем классе CMAR. Благодаря веселым обсуждениям, ролевым играм и групповым занятиям вы обретете уверенность в самовыражении и участии в содержательных беседах. Наши опытные преподаватели обеспечивают благоприятную среду обучения, направляя вас на путь к открытию языка."]},{image:"\u002Fimages\u002Ficons\u002Fsuitcase.png",title:"Деловой английский ＋ TOEIC®",subtitle:["Тест TOEIC® является показателем владения английским языком в бизнесе и используется различными компаниями и организациями по всему миру. В дополнение к стандартным бизнес-курсам курс TOEIC® готовит студентов к успеху на TOEIC® - экзамен по аудированию и чтению, введя существенный лексикон и исследуя стратегии достижения высокого балла на тесте.","Этот курс поможет вам улучшить ваши знания английского языка, такие как словарный запас, чтение, аудирование и грамматика. Изучив стратегии поиска правильных ответов, вы сможете получить высокий балл."]}]},schedule:"\u002Fimages\u002Fhome\u002Fen\u002Ffree_trial_banner-En.png",link:"\u002Fru\u002Ffreetrial",partnerSchools:{title:"MLI's Partner Universities \u002F Colleges",subtitle:"\"MLI students can enroll at partner universities or colleges after completing certain MLI programs.\""},locationCampus:{title:"Месторосположение\u002FКампусы",lists:[{image:"\u002Fimages\u002Fhome\u002Flocation-campus-1.jpg",title:"Вествуд Кампус",subtitle:"Вествуд - яркий, уникальный район, расположенный в западной части Лос-Анджелеса. Вествуд славится тем, что является домом для UCLA. Это очень интересная и популярная местность для студентов, так как здесь много студентов из университета и множество магазинов, ресторанов и безопасных мест для тусовки.",read_more:["\u003Ca href=\"\u002Fru\u002Fwestwood\u002F\"\u003E» Читать больше\u003C\u002Fa\u003E"]},{image:"\u002Fimages\u002Fhome\u002Flocation-campus-2.jpg",title:"Голливуд Кампус",subtitle:"Голливуд кампус находится рядом с знаменитым китайским театром. В районе Голливудв есть знаменитые кинотеатры, хорошие рестораны, магазины и клубы, и этот район всегда очень оживлен.",read_more:["\u003Ca href=\"\u002Fru\u002Fhollywood\u002F\"\u003E» Читать больше\u003C\u002Fa\u003E"]}]},testimonials:{title:"Отзывы студентов",seemoreBtn:"Посмотреть больше",TestimonialLink:"\u002Fru\u002Ftestimonials",readmoreBtn:"Читать далее"},dir:"\u002Fhome",path:"\u002Fhome\u002Fru",extension:".json",createdAt:"2026-10-22T16:31:29.608Z",updatedAt:"2025-05-26T12:06:27.785Z"},lang:b}],fetch:{},mutations:void 0}}("\u003Ca href=\"\u002Fru\u002Ffeature\u002F\"\u003E» Читать больше\u003C\u002Fa\u003E","ru","Отличная школа английского языка в Лос-Анджелесе по доступной цене| Mentor Language Institute","\u002Fimages\u002Ficons\u002Fpaste.png","\u002Fimages\u002Ficons\u002Fpen.png")));